  evt asegs mz_Q
    (MS (mkR ra (Z_to_bv 64 (bv_unsigned sp - 16)) gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 0) a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xdd6f4) fc None m (seg_rom asegs)).
